[CmdletBinding()] param([switch]$All,[switch]$Dotnet,[switch]$Python,[switch]$Node,[switch]$Cpp,[switch]$Pio,[switch]$Terraform,[switch]$Buf,[switch]$Check,[switch]$NoSudo)
$ErrorActionPreference='Stop'; $ScriptDir=Split-Path -Parent $MyInvocation.MyCommand.Path; $RootDir=Split-Path -Parent $ScriptDir; . (Join-Path $ScriptDir 'lib/common.ps1')
$explicit=$Dotnet -or $Python -or $Node -or $Cpp -or $Pio -or $Terraform -or $Buf; if(-not $explicit -and -not $Check){$All=$true}; if($All){$Dotnet=$Python=$Node=$Cpp=$Pio=$Terraform=$Buf=$true}
Write-Step 'Conjunto Inteligente · Bootstrap host (Windows)'; Write-Info "Root: $RootDir"
if($Check){& (Join-Path $ScriptDir 'verify.ps1'); exit $LASTEXITCODE}
if(-not(Acquire-Lock)){exit 1}; try { $failed=@(); function Invoke-Installer{param($Name,$Script); Write-Step "Instalando $Name"; try{& $Script;if($LASTEXITCODE -and $LASTEXITCODE -ne 0){throw "Exit code $LASTEXITCODE"};Write-Ok "$Name completado"}catch{Write-Err "$Name falló: $_";$script:failed+=$Name} }
 if($Dotnet){Invoke-Installer dotnet (Join-Path $ScriptDir 'install/dotnet.ps1')}; if($Python){Invoke-Installer python (Join-Path $ScriptDir 'install/python.ps1')}; if($Node){Invoke-Installer node (Join-Path $ScriptDir 'install/node.ps1')}; if($Cpp){Invoke-Installer cpp-deps (Join-Path $ScriptDir 'install/cpp-deps.ps1')}; if($Pio){Invoke-Installer platformio (Join-Path $ScriptDir 'install/platformio.ps1')}; if($Terraform){Invoke-Installer terraform (Join-Path $ScriptDir 'install/terraform.ps1')}; if($Buf){Invoke-Installer buf (Join-Path $ScriptDir 'install/buf.ps1')}; Write-Step 'Verificación'; & (Join-Path $ScriptDir 'verify.ps1'); $v=$LASTEXITCODE; if($failed.Count -gt 0){Write-Err "Instaladores fallidos: $($failed -join ', ')";exit 4};if($v -ne 0){exit $v}; Write-Step 'Listo'; Write-Host "Recarga PowerShell. Luego: docker compose up -d; dotnet build ConjuntoInteligente.sln" } finally {Release-Lock}
